	definition, err := dictionary.Search("test")
	if err != nil {
		t.Fatalf("Search for a known word reported %q, want no failure", err.Error())
	}
	if want := "this is just a test"; definition != want {
		t.Errorf("Search(%q) = %q, want %q", "test", definition, want)
